import { useState, type ChangeEvent } from 'react';
import { useIsMutating, useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { ClaimCells } from '../../slots/defs/claimRow';
import { PersonCells, PersonHeads } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/useSession';
import { useHeld } from '../people/people.slot';
import { claimLockKey, claimSaveKey, claimsKey, sumAmounts, useClaims, useEditingClaim, type Claim } from './useClaims';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useTemplates } from '../templates/templates.slot';

const AMOUNT = /^-?\d+(\.\d{1,2})?$/;

type ClaimBody = { amount: string; date: string; note: string; corrects: string; ref: string; tags: string };

// A person's claim form: adds a claim, or — with one of their claims' editor open — saves its
// changes. It is re-mounted for each claim opened, so it starts filled with that claim's values.
// Its template select adds a DRAFT claim from a sheet's template (its amount and note as they stand
// then, no date) by the same rules; a refusal shows in the form's error.
function ClaimForm({ sheetId, personId, editing }: { sheetId: string; personId: number; editing?: Claim }) {
  const [, setEditing] = useEditingClaim();
  const [amount, setAmount] = useState(editing?.amount ?? '');
  const [date, setDate] = useState(editing?.date ?? '');
  const [note, setNote] = useState(editing?.note ?? '');
  const [corrects, setCorrects] = useState(editing?.corrects ?? '');
  const [ref, setRef] = useState(editing?.ref ?? '');
  const [tags, setTags] = useState(editing?.tags.join(', ') ?? '');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const sheet = `/api/sheets/${encodeURIComponent(sheetId)}`;
  const save = useMutation({
    mutationKey: claimSaveKey(sheetId),
    mutationFn: async (body: ClaimBody) => {
      if (body.amount.trim() === '') throw new Error('Enter an amount');
      if (!AMOUNT.test(body.amount.trim())) throw new Error('An amount is a number with up to two decimals');
      // `by` is the signed-in user the change is recorded against.
      const sent = { ...body, by: user ?? '' };
      return editing
        ? putJson<Claim>(`${sheet}/claims/${editing.id}`, sent)
        : postJson<Claim>(`${sheet}/people/${personId}/claims`, sent);
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      if (editing) {
        setEditing(undefined);
      } else {
        setAmount('');
        setDate('');
        setNote('');
        setCorrects('');
        setRef('');
        setTags('');
      }
    },
  });
  const templates = useTemplates(sheetId);
  const [template, setTemplate] = useState('');
  const fromTemplate = useMutation({
    mutationFn: async (name: string) => {
      if (name === '') throw new Error('Choose a template');
      return postJson<Claim>(`${sheet}/people/${personId}/claims/template`, { template: name, by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });
  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
    fromTemplate.reset();
  };

  // While a claim's editor is being opened, the form may be about to become its editor: it waits.
  const locking = useIsMutating({ mutationKey: claimLockKey(sheetId) }) > 0;
  const submit = useSubmitOnce(save);
  const submitTemplate = useSubmitOnce(fromTemplate);
  const error = save.error ?? fromTemplate.error;
  return (
    <form
      data-testid="claim-form"
      onSubmit={(e) => {
        e.preventDefault();
        fromTemplate.reset();
        submit({ amount, date, note, corrects, ref, tags });
      }}
    >
      <input data-testid="claim-form-amount" placeholder="Amount" inputMode="decimal" value={amount} onChange={field(setAmount)} />{' '}
      <input data-testid="claim-form-date" type="date" value={date} onChange={field(setDate)} />{' '}
      <input data-testid="claim-form-note" placeholder="Note" value={note} onChange={field(setNote)} />{' '}
      <input data-testid="claim-form-corrects" placeholder="Corrects no." value={corrects} onChange={field(setCorrects)} />{' '}
      <input data-testid="claim-form-ref" placeholder="Reference" value={ref} onChange={field(setRef)} />{' '}
      <input data-testid="claim-form-tags" placeholder="Tags, comma separated" value={tags} onChange={field(setTags)} />{' '}
      <button type="submit" data-testid="claim-form-submit" disabled={save.isPending || locking}>
        {editing ? 'Save claim' : 'Add claim'}
      </button>
      {!editing && (
        <>
          {' '}
          <select
            data-testid="claim-template-select"
            value={template}
            onChange={(e) => {
              setTemplate(e.target.value);
              save.reset();
              fromTemplate.reset();
            }}
          >
            <option value="">Template…</option>
            {(templates.data ?? []).map((t) => (
              <option key={t.name} value={t.name}>
                {t.name}
              </option>
            ))}
          </select>{' '}
          <button
            type="button"
            data-testid="claim-template-add"
            disabled={fromTemplate.isPending || locking}
            onClick={() => {
              save.reset();
              submitTemplate(template);
            }}
          >
            Add from template
          </button>
        </>
      )}
      {error && (
        <p data-testid="claim-form-error" role="alert">
          {error.message}
        </p>
      )}
    </form>
  );
}

function ClaimsHead() {
  return (
    <>
      <th>Claimed</th>
      <th>Claims</th>
    </>
  );
}

// A person's claimed total, and their claims, newest first, under the form that adds or edits them. A claim's edit and
// cancel buttons are in its status cell, with its locking.
function ClaimsCells({ sheetId, user, personId }: { sheetId: string; user: string; personId: number }) {
  const claims = useClaims(sheetId);
  const [editingId] = useEditingClaim();
  const held = useHeld(sheetId);
  const mine = (claims.data ?? []).filter((c) => c.personId === personId);
  const editing = mine.find((c) => c.id === editingId);

  return (
    <>
      <td data-testid="person-claimed">{sumAmounts(mine, held)}</td>
      <td>
        <ClaimForm key={editing ? `edit-${editing.id}` : 'add'} sheetId={sheetId} personId={personId} editing={editing} />
        <ul data-testid="claim-list">
          {mine.map((c) => (
            <li key={c.id} data-testid={`claim-row-${c.id}`}>
              <span data-testid="claim-amount">{Number(c.amount).toFixed(2)}</span>{' '}
              <span data-testid="claim-date">{c.date}</span>{' '}
              <span data-testid="claim-note">{c.note}</span>{' '}
              <span data-testid="claim-corrects">{c.corrects ?? ''}</span>{' '}
              <span data-testid="claim-ref">{c.ref ?? ''}</span>{' '}
              <span data-testid="claim-tags">{c.tags.join(', ')}</span>{' '}
              <ClaimCells.Slot sheetId={sheetId} user={user} personId={personId} claim={c} />
            </li>
          ))}
        </ul>
      </td>
    </>
  );
}

// The sheet's claimed-total: everyone's counted claims added up.
function ClaimedTotal({ sheetId }: { sheetId: string; user: string }) {
  const claims = useClaims(sheetId);
  const held = useHeld(sheetId);
  return (
    <section data-testid="claims-rollup">
      <p>
        Claimed total: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [], held)}</strong>
      </p>
      {claims.isError && (
        <p data-testid="claims-error" role="alert">
          {claims.error.message}
        </p>
      )}
    </section>
  );
}

export const contributions = [
  PersonHeads.fill({ order: 10, Component: ClaimsHead }),
  PersonCells.fill({ order: 10, Component: ClaimsCells }),
  SheetBody.fill({ order: 20, Component: ClaimedTotal }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import type { Holds } from '../people/people.slot';

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED';

export type Claim = { id: number; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  /** Given when the claim is opened: the sheet's next (1, 2, ...), or within its period (<period>-<n>, X-<n> in none); none for a draft. */
  number: string | null;
  /** The due fixed when the claim was settled; none while live (not settled, or settled without a rate). */
  settledDue: string | null;
  /** The signed-in user who opened the claim; none when it was never opened. They cannot settle it. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals `statedDue` (none: n/a). */
  stated: boolean;
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; none for any other claim. */
  corrects: string | null;
  /** The date the claim is due by: the terms-th business day after its date when added (skipping Saturdays, Sundays and the sheet's holidays now), by the terms fixed then. */
  dueBy: string;
  /** The claim's status log, oldest first: `<STATUS> by <user> on <date> due=<due>`. */
  log: string[];
  /** Whether the OPEN claim is deferred past the sheet's today: it then counts in no total, is not overdue and cannot be settled. */
  deferred: boolean;
  /** The date it was last deferred until; none when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim carries; one above the proof threshold needs one before it is settled or approved. */
  proofs: number;
  /** The number of the claim this one was split off; none when it was not split off one. */
  splitFrom: string | null;
  /** Whether it was added while the period containing its due-by was soft-closed. */
  lateEntry: boolean;
  /** The last sheet-today a reminder was written for the claim; none when it was never reminded. */
  reminded: string | null;
  /** The claim's external reference, used at most once on the sheet (case aside); none when it has none. */
  ref: string | null;
  /** The claim's tags, sorted; empty when it has none. */
  tags: string[];
  /** The reason the claim was voided with, from the sheet's list; none when none was given. */
  voidReason: string | null;
  /** The claim's comments, oldest first: `<user> on <date>: <text>` (the sheet's today when written). */
  comments: string[];
  /** The number of the bulk settle batch that settled the claim; none when no batch settled it. */
  settleBatch: number | null };

/** Whether a claim counts toward claimed, due and every total: only OPEN, PENDING and SETTLED claims do, and an OPEN
 *  or PENDING one dated within one of its person's holds (`held`: each person's holds) does not unless a statement binds it;
 *  nor does one deferred past the sheet's today. */
export function counts(claim: { status: ClaimStatus; personId: number; date: string; stated: boolean; deferred?: boolean }, held: Holds): boolean {
  if (claim.deferred) return false;
  if (claim.status === 'OPEN' || claim.status === 'PENDING') {
    return claim.stated || !(held.get(claim.personId) ?? []).some((h) =>
      (h.from === null || h.from <= claim.date) && (h.to === null || claim.date <= h.to));
  }
  return claim.status === 'SETTLED';
}

/** The key every feature reads the sheet's claims under. */
export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** The key of a claim editor's lock request: a claim form waits for it before it submits. */
export const claimLockKey = (sheetId: string) => ['sheet', sheetId, 'claim-lock'] as const;

/** The key of a claim form's save: saving a claim's editor clears the claim's lock refusal. */
export const claimSaveKey = (sheetId: string) => ['sheet', sheetId, 'claim-save'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** Every tag ever used on the sheet's claims, sorted; under the claims' key, so whatever refreshes the claims refreshes it. */
export function useClaimTags(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'tags'] as const,
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/tags`),
  });
}

/** The number of the sheet's last bulk settle batch (none when there has been none); under the claims' key, so
 *  whatever refreshes the claims refreshes it. */
export function useLastSettleBatch(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'settle-batch'] as const,
    queryFn: () => getJson<{ batch: number | null }>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/settle-batch`),
  });
}

/** Which claim's editor is open (search param `editClaim`); none means each claim form adds. */
export function useEditingClaim() {
  return useSearchParam('editClaim', asNumber);
}

/** The counted claims' amounts added up exactly, in cents, shown with two decimals. */
export function sumAmounts(claims: Claim[], held: Holds): string {
  const cents = claims.filter((c) => counts(c, held)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}
